#ifndef ASTERIA_PLATFORM_AMD64_SCHEDULER_AMD64_APPLICATION_PROCESSOR_RUNTIME_HPP_INCLUDED
#define ASTERIA_PLATFORM_AMD64_SCHEDULER_AMD64_APPLICATION_PROCESSOR_RUNTIME_HPP_INCLUDED

#include "Kernel/Memory/TlbShootdownDrain.hpp"
#include "Kernel/Object/RootCapabilityIssuer.hpp"
#include "Kernel/Resource/ResourceDomain.hpp"
#include "Kernel/Time/DeferredTimerWorker.hpp"
#include "Platform/Amd64/Interrupt/Amd64UserEntry.hpp"
#include "Platform/Amd64/Scheduler/Amd64ProcessorRunLoop.hpp"
#include "Platform/Amd64/Time/Amd64ApicTimer.hpp"
#include "Platform/Amd64/System/Amd64WaitRuntime.hpp"
#include "Platform/Synchronization/AtomicUInt64.hpp"

namespace Asteria::Kernel::System { class ObjectManager; }
namespace Asteria::Platform::Amd64::System { class Amd64UserThreadTable; }
namespace Asteria::Platform::Amd64::Scheduler
{
struct Amd64ApplicationProcessorInput
{
    Kernel::Object::ObjectRegistry* Registry;
    Kernel::Resource::ResourceDomain* Resources;
    Kernel::Resource::ResourceDomainObjectId ResourceIdentity;
    Kernel::Memory::AddressSpace* SharedSpace;
    Kernel::Memory::AddressSpace* IdleSpace;
    System::Amd64UserThreadTable* UserThreads;
    Kernel::System::ObjectManager* Objects;
    Interrupt::Amd64DescriptorTables* Descriptors;
    Interrupt::Amd64EntryContext* EntryContext;
    WritableAmd64KernelStackView WorkerStack;
    Foundation::UInt64 ApicAddress;
    Kernel::Scheduler::CpuId Processor;
    Foundation::UInt32 HardwareId;
    bool X2Apic;
};

/// What an application processor observed while it proved its local timer
/// and one deferred timer delivery, before it reported serving. The worker's
/// first dispatch has blocked it (InitialRuns); a TimerQueue timer armed for
/// RequestedDeadlineTicks raised ObservedInterrupts local-timer interrupts by
/// ObservedTicks; the DeferredTimerWorker then drained the queue (the drain
/// receipt's count, stop reason and final queue state, and whether every
/// delivered timer was the AP's own), the AP claimed and consumed the
/// Notification, and the controller refreshed the deadline (its state, the
/// local timer's deadline, and the xAPIC LVT timer entry and initial count
/// read back afterwards). Counts, sequences and states are recorded as
/// observed; the kernel does not compare them with what the scenario expects.
/// Enumerations are stored as their underlying values.
struct Amd64ApplicationProcessorTimerObservation
{
    Foundation::UInt64 InitialRuns;
    Foundation::UInt64 RequestedDeadlineTicks;
    Foundation::UInt64 ObservedTicks;
    Foundation::UInt64 ObservedInterrupts;
    Foundation::UInt64 DeliveredCount;
    Foundation::UInt64 DrainStop;
    Foundation::UInt64 DeliveredOwnTimer;
    Foundation::UInt64 QueueNextDeadlineTicks;
    Foundation::UInt64 QueueScheduledEntries;
    Foundation::UInt64 QueuePendingEntries;
    Foundation::UInt64 QueueClaimedEntries;
    Foundation::UInt64 NotificationClaimSequence;
    Foundation::UInt64 NotificationState;
    Foundation::UInt64 NotificationPending;
    Foundation::UInt64 NotificationLastClaimSequence;
    Foundation::UInt64 DisarmedDeadlineState;
    Foundation::UInt64 DisarmedDeadlineTicks;
    Foundation::UInt64 DisarmedTimerLvt;
    Foundation::UInt64 DisarmedInitialCount;
};

/// One CPU's permanent kernel service context. The BSP constructs it before
/// INIT/SIPI. Service requests have one publisher, one outstanding sequence,
/// and an acquire/release acknowledgement before arguments may be reused.
/// The AP initiates a system stop (ApplicationProcessorStage) when one of its operations is
/// rejected or its scheduler or timer is not in the state the next step
/// requires; what its diagnostic timer scenario observed is recorded
/// (GetTimerObservation), not judged.
class Amd64ApplicationProcessorRuntime final
{
public:
    explicit Amd64ApplicationProcessorRuntime(const Amd64ApplicationProcessorInput& input) noexcept;
    [[noreturn]] void Run() noexcept;
    [[nodiscard]] bool OnTimerInterrupt() noexcept;
    void EnableUsers() noexcept { m_usersEnabled.StoreRelease(1U); }
    void EndOfInterrupt() noexcept { m_timer.EndOfInterrupt(); }
    [[nodiscard]] Time::Amd64ApicTimer& GetLocalTimer() noexcept { return m_timer; }
    [[nodiscard]] Kernel::Scheduler::ProcessorRunController& GetController() noexcept { return m_controller; }
    [[nodiscard]] Amd64ProcessorRunLoop& GetRunLoop() noexcept { return m_loop; }
    [[nodiscard]] System::Amd64WaitRuntime& GetWaitRuntime() noexcept { return m_waitRuntime; }
    /// Publishes the next service request (one outstanding at a time); it is
    /// complete once GetCompleted() reaches the previous count plus one.
    [[nodiscard]] bool RequestService(Foundation::UInt64 address = 0U) noexcept;
    [[nodiscard]] Foundation::UInt64 GetState() const noexcept;
    [[nodiscard]] Foundation::UInt64 GetCompleted() const noexcept;
    [[nodiscard]] Foundation::UInt64 GetRuns() const noexcept;
    [[nodiscard]] Foundation::UInt64 GetTimerInterrupts() const noexcept;
    [[nodiscard]] Foundation::UInt64 GetTimerDeliveries() const noexcept;
    /// The word the worker read at the address of the last completed request.
    [[nodiscard]] Foundation::UInt64 GetObservation() const noexcept;
    /// Valid once GetState() returned 1 (the acquire orders it after the AP's writes).
    [[nodiscard]] const Amd64ApplicationProcessorTimerObservation& GetTimerObservation() const noexcept;
    /// Before the first startup IPI only; the drain remains valid permanently.
    void BindDrain(Kernel::Memory::ITlbShootdownDrain& drain) noexcept;
private:
    [[nodiscard, gnu::noinline]] bool PrepareObjects() noexcept;
    [[nodiscard, gnu::noinline]] bool AdmitWorker() noexcept;
    [[nodiscard, gnu::noinline]] bool WakeWorker() noexcept;
    [[nodiscard, gnu::noinline]] bool DispatchBlocked() noexcept;
    [[noreturn, gnu::noinline]] static void Worker(void* argument) noexcept;
    [[noreturn]] void Fail(Foundation::UInt64 stage) noexcept;
    void Service() noexcept;
    [[nodiscard, gnu::noinline]] bool ServiceUsers() noexcept;
    [[nodiscard]] bool ProbeTimer() noexcept;
    [[nodiscard, gnu::noinline]] bool PrepareTimerDelivery() noexcept;
    [[nodiscard, gnu::noinline]] bool CompleteTimerDelivery() noexcept;

    Amd64ApplicationProcessorInput m_input;
    Kernel::Object::RootCapabilityIssuer m_issuer;
    Time::Amd64ApicTimer m_timer;
    Kernel::Time::TimerQueue m_queue;
    Kernel::Scheduler::ProcessorRunController m_controller;
    Kernel::Memory::ProcessorAddressSpaceController m_addressSpaces;
    Amd64KernelContext m_idle;
    Amd64KernelContext m_worker;
    Amd64ProcessorRunLoop m_loop;
    System::Amd64WaitRuntime m_waitRuntime;
    Kernel::Protection::ProtectionDomain m_protection;
    Kernel::Scheduler::Thread m_thread;
    Kernel::Scheduler::SchedulingContext m_scheduling;
    Kernel::Time::Timer m_timerObject;
    Kernel::Ipc::Notification m_notification;
    Kernel::Time::DeferredTimerWorker m_deferred;
    Kernel::Time::TimerId m_timerId{};
    Kernel::Scheduler::ThreadId m_threadId{};
    Kernel::Scheduler::SchedulingContextId m_schedulingId{};
    Kernel::Scheduler::ProcessorKernelRunLoopReceipt m_idleReceipt{};
    Kernel::Scheduler::ProcessorKernelRunLoopFailure m_idleFailure{};
    Kernel::Scheduler::ProcessorKernelRunLoopReceipt m_workerReceipt{};
    Kernel::Scheduler::ProcessorKernelRunLoopFailure m_workerFailure{};
    Kernel::Memory::ITlbShootdownDrain* m_drain{nullptr};
    Synchronization::AtomicUInt64 m_usersEnabled;
    bool m_idleAdopted{false};
    Foundation::UInt64 m_idleEntryStackTop{0U};
    Synchronization::AtomicUInt64 m_state;
    Synchronization::AtomicUInt64 m_requested;
    Synchronization::AtomicUInt64 m_completed;
    Synchronization::AtomicUInt64 m_runs;
    Synchronization::AtomicUInt64 m_timerInterrupts;
    Synchronization::AtomicUInt64 m_timerDeliveries;
    Foundation::UInt64 m_observeAddress{0U};
    Foundation::UInt64 m_observation{0U};
    Amd64ApplicationProcessorTimerObservation m_timerObservation{};
};

static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, InitialRuns) == 0U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, RequestedDeadlineTicks) == 8U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, ObservedTicks) == 16U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, ObservedInterrupts) == 24U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DeliveredCount) == 32U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DrainStop) == 40U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DeliveredOwnTimer) == 48U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, QueueNextDeadlineTicks) == 56U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, QueueScheduledEntries) == 64U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, QueuePendingEntries) == 72U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, QueueClaimedEntries) == 80U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, NotificationClaimSequence) == 88U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, NotificationState) == 96U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, NotificationPending) == 104U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, NotificationLastClaimSequence) == 112U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DisarmedDeadlineState) == 120U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DisarmedDeadlineTicks) == 128U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DisarmedTimerLvt) == 136U);
static_assert(__builtin_offsetof(Amd64ApplicationProcessorTimerObservation, DisarmedInitialCount) == 144U);
static_assert(sizeof(Amd64ApplicationProcessorTimerObservation) == 152U);
} // namespace Asteria::Platform::Amd64::Scheduler
#endif

sources.Source/Platform/Amd64/Interrupt/Amd64Use:
#ifndef ASTERIA_PLATFORM_AMD64_INTERRUPT_AMD64_USER_ENTRY_HPP_INCLUDED
#define ASTERIA_PLATFORM_AMD64_INTERRUPT_AMD64_USER_ENTRY_HPP_INCLUDED

#include "Foundation/Types.hpp"

namespace Asteria::Platform::Amd64::Interrupt
{
inline constexpr Foundation::UInt16 KernelCodeSelector{0x08U};
inline constexpr Foundation::UInt16 KernelDataSelector{0x10U};
inline constexpr Foundation::UInt16 UserDataSelector{0x1BU};
inline constexpr Foundation::UInt16 UserCodeSelector{0x23U};
inline constexpr Foundation::UInt16 TaskStateSelector{0x28U};
inline constexpr Foundation::UInt64 SystemCallVector{256U};

/// RFLAGS of a CPL3 return (SanitizeUserFlags, IsUserReturnValid). IF and the
/// reserved bit 1 are always set. The permitted bits beyond those are the
/// flags CPL3 code can change itself with POPF, except TF: CF, PF, AF, ZF, SF,
/// DF, OF, NT, AC and ID, which a system call returns as the program left
/// them. TF (a supervised user debug trap is an Exception that terminates
/// that thread), IOPL, RF, VM, VIF, VIP and the reserved
/// bits are clear.
inline constexpr Foundation::UInt64 UserReturnRequiredFlags{0x202U};
inline constexpr Foundation::UInt64 UserReturnPermittedFlags{0x24'4ED7U};
/// Control-register policy Install applies on every CPU, the BSP after its initial activation and
/// each AP right after its startup code. CR0.MP and CR0.NE are set and CR0.EM and CR0.TS cleared,
/// so x87 and SSE instructions run and report their errors as exceptions; every context switch
/// saves and restores that state eagerly, so nothing traps on its first use. CR0.AM is cleared
/// (RFLAGS.AC, which user code may set, then enables no alignment check); the other CR0 bits keep
/// what the activation checked (PE, WP and PG set, CD and NW clear) or the startup code chose. CR4
/// is written whole, so no CPU keeps a firmware- or startup-dependent CR4 bit: PAE (IA-32e paging),
/// MCE (a machine check reaches its terminal IST handler instead of shutting the processor down),
/// OSFXSR (FXSAVE/FXRSTOR and SSE) and OSXMMEXCPT (SIMD floating-point errors raise #XM). Every
/// other CR4 bit is clear: no global pages, PCIDs or five-level paging (the root backend and the
/// initial activation), no FSGSBASE (user FS and GS bases stay zero), no SMEP or SMAP (not enabled
/// by this profile), no OSXSAVE (FXSAVE covers SSE; XSAVE is later), and no DE, TSD, PCE, UMIP,
/// VMXE, SMXE, PKE, CET, PKS, LASS or LAM.
inline constexpr Foundation::UInt64 InstalledControlRegister0Set{0x22U};
inline constexpr Foundation::UInt64 InstalledControlRegister0Clear{0x4'000CU};
inline constexpr Foundation::UInt64 InstalledControlRegister4{0x660U};

/// CPUID leaf 1 EDX bits every processor must report: FXSR, SSE and SSE2.
inline constexpr Foundation::UInt32 RequiredProcessorFeatures{(1U << 24U) | (1U << 25U) | (1U << 26U)};

/// The RFLAGS a CPL3 return restores for the user image `flags`: its
/// permitted bits, with IF and bit 1 set and every other bit clear.
[[nodiscard]] constexpr Foundation::UInt64 SanitizeUserFlags(const Foundation::UInt64 flags) noexcept
{
    return (flags & UserReturnPermittedFlags) | UserReturnRequiredFlags;
}

/// Stack image shared by SYSCALL and interrupt entry. Every field is owned
/// supervisor memory; no address supplied by user mode selects this storage.
struct Amd64TrapFrame
{
    Foundation::UInt64 R15;
    Foundation::UInt64 R14;
    Foundation::UInt64 R13;
    Foundation::UInt64 R12;
    Foundation::UInt64 R11;
    Foundation::UInt64 R10;
    Foundation::UInt64 R9;
    Foundation::UInt64 R8;
    Foundation::UInt64 Rbp;
    Foundation::UInt64 Rdi;
    Foundation::UInt64 Rsi;
    Foundation::UInt64 Rdx;
    Foundation::UInt64 Rcx;
    Foundation::UInt64 Rbx;
    Foundation::UInt64 Rax;
    Foundation::UInt64 Vector;
    Foundation::UInt64 Error;
    Foundation::UInt64 Rip;
    Foundation::UInt64 Cs;
    Foundation::UInt64 Rflags;
    Foundation::UInt64 Rsp;
    Foundation::UInt64 Ss;
};

struct alignas(16U) Amd64EntryContext
{
    Foundation::UInt64 KernelStackTop;
    Foundation::UInt64 UserStackScratch;
    Foundation::UInt64 Processor;
    Foundation::UInt64 Reserved;
};

/// Processor-owned tables. TSS fields are encoded bytewise, including its
/// unaligned 64-bit stack pointers. The I/O bitmap starts beyond the limit.
struct alignas(4096U) Amd64DescriptorTables
{
    Foundation::UInt64 Gdt[8U];
    Foundation::UInt8 Tss[104U];
    Foundation::UInt8 Gdtr[10U];
    Foundation::UInt8 Idtr[10U];
    Foundation::UInt8 Padding[3908U];
    Foundation::UInt64 Idt[512U];
};

enum class Amd64UserEntryError : Foundation::UInt8
{
    None,
    InvalidContext,
    InvalidStack,
    InvalidHandler,
    InvalidUserFrame,
};

class Amd64UserEntry final
{
public:
    Amd64UserEntry() = delete;

    /// Caller retains exclusive ownership of tables and context, and proves
    /// all four stacks are mapped supervisor RW/NX with distinct guard pages.
    [[nodiscard]] static Amd64UserEntryError Prepare(
        Amd64DescriptorTables& tables,
        const Amd64EntryContext& context,
        Foundation::UInt64 emergencyStackTop,
        Foundation::UInt64 nmiStackTop,
        Foundation::UInt64 machineCheckStackTop,
        const Foundation::UInt64* handlers,
        Foundation::Size handlerCount) noexcept;

    /// Whether IRETQ may restore `frame` to CPL3: the exact user selectors, a
    /// RIP in the lower canonical half above page zero, and RFLAGS equal to
    /// SanitizeUserFlags(RFLAGS). RSP is the program's own state and is not
    /// examined: IRETQ restores any value, and a stack the program cannot use
    /// faults in the program. Selectors and sanitized flags are kernel
    /// invariants; a rejected user RIP must fault only its thread.
    [[nodiscard]] static bool IsUserReturnValid(
        const Amd64TrapFrame& frame) noexcept;

    /// Makes a SYSCALL frame (the system-call vector) returnable: RFLAGS, the
    /// program's R11 image, becomes SanitizeUserFlags(RFLAGS); RSP and every
    /// other field stay unchanged. Legal user state (any flags POPF can set,
    /// any RSP) is never rejected. Returns false, changing nothing, when the
    /// frame is not a SYSCALL frame or IsUserReturnValid fails after the
    /// sanitization.
    [[nodiscard]] static bool PrepareSystemCallReturn(
        Amd64TrapFrame& frame) noexcept;

    /// An entry-authenticated SYSCALL with an unusable user return address.
    /// Deliver it as a supervised exception before any IRETQ or dispatch.
    [[nodiscard]] static bool IsSystemCallReturnFault(const Amd64TrapFrame& frame) noexcept;

    /// An entry-authenticated user frame with an unusable RIP, also after an interrupted fault
    /// yields behind a busy supervisor.
    [[nodiscard]] static bool IsUserReturnAddressFault(const Amd64TrapFrame& frame) noexcept;

    /// Owning CPU only, IF clear, mapped immutable code/tables/context and
    /// pinned stacks. Installs GDT, TSS, IDT, GS and the SYSCALL MSRs, and
    /// applies the control-register policy (InstalledControlRegister0Set,
    /// InstalledControlRegister0Clear, InstalledControlRegister4). Extended
    /// user state remains disabled until an extended-state owner is installed.
    static void Install(
        Amd64DescriptorTables& tables,
        Amd64EntryContext& context) noexcept;

    /// Owning CPU only, IF clear, after Install. Makes `kernelStackTop` the
    /// stack of the next CPL3 entry: both RSP0 of the TSS (interrupts and
    /// exceptions) and the SYSCALL stack top of the entry context. Each user
    /// thread owns its kernel stack, so the dispatcher selects the stack of
    /// the thread it returns to before every CPL3 return. The caller proves
    /// the stack is a mapped supervisor RW/NX stack with a guard page below
    /// it; the top is rejected, changing nothing, when it is not a canonical
    /// page boundary of at least 8 KiB.
    [[nodiscard]] static bool SelectKernelStack(
        Amd64DescriptorTables& tables,
        Amd64EntryContext& context,
        Foundation::UInt64 kernelStackTop) noexcept;

    /// Enters one validated CPL3 frame and abandons the current C++ call.
    [[noreturn]] static void Enter(Amd64TrapFrame& frame) noexcept;
};

extern "C" const Foundation::UInt64 AsteriaAmd64InterruptHandlers[256U];
extern "C" void AsteriaAmd64SystemCallEntry() noexcept;
extern "C" void AsteriaAmd64DispatchTrap(Amd64TrapFrame* frame) noexcept;

static_assert(sizeof(Amd64TrapFrame) == 176U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R15) == 0U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R14) == 8U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R13) == 16U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R12) == 24U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R11) == 32U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R10) == 40U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R9) == 48U);
static_assert(__builtin_offsetof(Amd64TrapFrame, R8) == 56U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rbp) == 64U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rdi) == 72U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rsi) == 80U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rdx) == 88U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rcx) == 96U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rbx) == 104U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rax) == 112U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Vector) == 120U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Error) == 128U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rip) == 136U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Cs) == 144U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rflags) == 152U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Rsp) == 160U);
static_assert(__builtin_offsetof(Amd64TrapFrame, Ss) == 168U);
static_assert(sizeof(Amd64EntryContext) == 32U);
static_assert(sizeof(Amd64DescriptorTables) == 8192U);
static_assert(__builtin_offsetof(Amd64DescriptorTables, Idt) == 4096U);
} // namespace Asteria::Platform::Amd64::Interrupt

#endif // ASTERIA_PLATFORM_AMD64_INTERRUPT_AMD64_USER_ENTRY_HPP_INCLUDED

